[CmdletBinding()]param()
$ErrorActionPreference='Stop';$tmp=Join-Path $env:TEMP ('spectra-uat-contract-'+[guid]::NewGuid().ToString('N'));try{foreach($profile in @('implementation','support-only')){$a=Join-Path $tmp "$profile-a";$b=Join-Path $tmp "$profile-b";& (Join-Path $PSScriptRoot 'New-SyntheticUatTrainingDefects.ps1') -Destination $a -Profile $profile|Out-Null;& (Join-Path $PSScriptRoot 'New-SyntheticUatTrainingDefects.ps1') -Destination $b -Profile $profile|Out-Null;$ha=(Get-FileHash (Join-Path $a 'uat-training-defects.json') -Algorithm SHA256).Hash;if($ha-ne(Get-FileHash (Join-Path $b 'uat-training-defects.json') -Algorithm SHA256).Hash){throw 'UAT_GENERATOR_NOT_DETERMINISTIC'};& (Join-Path $PSScriptRoot 'Test-UatTrainingDefects.ps1') -Path $a|Out-Null;$cli=& (Join-Path $PSScriptRoot 'Invoke-Spectra.ps1') -Command validate-uat-training-defects -Workspace $a|ConvertFrom-Json;if($cli.status-ne'VALIDATED'-or$cli.writes_performed-ne$false){throw 'UAT_CLI_INVALID'};$backup=Join-Path $tmp "$profile-backup";$restore=Join-Path $tmp "$profile-restore";& (Join-Path $PSScriptRoot 'Backup-Workspace.ps1') -Source $a -Destination $backup|Out-Null;& (Join-Path $PSScriptRoot 'Restore-Workspace.ps1') -Backup $backup -Destination $restore|Out-Null;if((Get-FileHash (Join-Path $restore 'uat-training-defects.json') -Algorithm SHA256).Hash-ne$ha){throw 'UAT_BACKUP_ROUNDTRIP_MISMATCH'};& (Join-Path $PSScriptRoot 'Test-UatTrainingDefects.ps1') -Path $restore|Out-Null};Write-Host 'PASS: Beide UAT-/Training-/Defect-Profile sind deterministisch, read-only und portabel.'}finally{if(Test-Path $tmp){Remove-Item $tmp -Recurse -Force -ErrorAction SilentlyContinue}}
